/* Generates openapi.yaml (API-012). Run: node scripts/gen-openapi.cjs */
const fs = require('node:fs');
const yaml = require('js-yaml');

const ERR = { $ref: '#/components/schemas/ErrorEnvelope' };
const errResp = (desc) => ({ description: desc, content: { 'application/json': { schema: ERR } } });
const common = {
  400: { $ref: '#/components/responses/ValidationError' },
  401: { $ref: '#/components/responses/Unauthenticated' },
  403: { $ref: '#/components/responses/Forbidden' },
  404: { $ref: '#/components/responses/NotFound' },
  409: { $ref: '#/components/responses/Conflict' },
  429: { $ref: '#/components/responses/RateLimited' },
  500: { $ref: '#/components/responses/Internal' },
};
const json = (schema, desc = 'OK') => ({ description: desc, content: { 'application/json': { schema } } });
const obj = (props, required) => ({ type: 'object', properties: props, ...(required ? { required } : {}) });
const str = (extra = {}) => ({ type: 'string', ...extra });
const int = (extra = {}) => ({ type: 'integer', ...extra });
const num = (extra = {}) => ({ type: 'number', ...extra });
const bool = () => ({ type: 'boolean' });
const uuid = () => str({ format: 'uuid' });
const dt = () => str({ format: 'date-time' });
const date = () => str({ format: 'date' });
const arr = (items) => ({ type: 'array', items });
const ref = (n) => ({ $ref: `#/components/schemas/${n}` });
const nullable = (s) => (s.$ref ? { type: 'object', allOf: [s], nullable: true } : { ...s, nullable: true });
const enumOf = (v) => str({ enum: v });
const q = (name, schema, required = false, description) => ({ name, in: 'query', required, schema, ...(description ? { description } : {}) });
const p = (name, schema = uuid()) => ({ name, in: 'path', required: true, schema });
const body = (schema, required = true) => ({ required, content: { 'application/json': { schema } } });
const dateOrDt = { type: 'string', description: 'YYYY-MM-DD or RFC 3339 date-time', example: '2026-09-01' };
const paged = (item) => obj({ data: arr(item), next_cursor: nullable(str()) }, ['data', 'next_cursor']);
const pageParams = [q('limit', int({ minimum: 1, maximum: 100, default: 25 })), q('cursor', str()), q('sort', str({ example: 'slot_start:desc' }))];

const roles = ['customer', 'technician', 'supervisor', 'manager', 'admin', 'finance'];
