const paths = {};
const add = (path, method, op) => {
  paths[path] ??= {};
  paths[path][method] = { responses: { ...common }, ...op, responses: { ...(op.responses ?? {}), ...common, ...(op.responses ?? {}) } };
  if (!paths[path][method].responses['200'] && !paths[path][method].responses['201'] && !paths[path][method].responses['204']) throw new Error(`no success response for ${method} ${path}`);
};
const T = { auth: 'Auth & profile', cat: 'Catalogue', veh: 'Vehicles', bk: 'Bookings', qt: 'Quotations', pay: 'Payments', loy: 'Loyalty', staff: 'Staff', inv: 'Inventory', adm: 'Admin', not: 'Notifications', sys: 'System' };

add('/health', 'get', { tags: [T.sys], operationId: 'getHealth', summary: 'Liveness probe', security: [], responses: { 200: json(obj({ ok: bool(), version: str(), service: str(), time: dt() })) } });

